describe('single default', () => {
  async function dict() {
    const code = `e2e_dict_entry.default${++seq}`
    await insertRow(ds.manager, 'cfg_dict', { code, name: code })
    dictCodes.push(code)
    return code
  }
  const entryBody = (code: string, over: object = {}) => body(unique(), { dictCode: code, ...over })
  const read = async (code: string): Promise<DictPayload> =>
    (
      await request(app.getHttpServer())
        .get(`/api/settings/dicts/${code}/entries`)
        .set(bearer(tokens.plain))
        .expect(200)
    ).body.data
  const defaults = (payload: DictPayload) =>
    payload.entries.filter((e) => e.isDefault).map((e) => e.value)
  const duplicate = (res: request.Response, lang = 'zh-CN') => {
    expect(res.status).toBe(409)
    expect(t(lang, Err.DUPLICATE.key)).not.toBe(Err.DUPLICATE.key)
    expect(res.body).toMatchObject({
      code: Err.DUPLICATE.code,
      msg: t(lang, Err.DUPLICATE.key),
      data: null,
      traceId: expect.any(String),
    })
  }

  it('create/PUT conflicts keep the old default and warm cache; an explicit unset permits switching', async () => {
    const code = await dict()
    const old = await add(entryBody(code, { isDefault: true }))
    const next = await add(entryBody(code))
    const before = await read(code)
    expect(defaults(before)).toEqual([old.value])
    const cacheKey = redisKey('dict', 'entries', code)
    expect(JSON.parse((await redis.get(cacheKey))!)).toEqual(before)

    for (const lang of ['zh-CN', 'en-US']) {
      duplicate(
        await create(entryBody(code, { isDefault: true })).set('Accept-Language', lang),
        lang,
      )
      expect(await read(code)).toEqual(before)
      duplicate(
        await call('admin', 'put', `/${next.id}`, { isDefault: true, label: 'rejected' }).set(
          'Accept-Language',
          lang,
        ),
        lang,
      )
      expect(await read(code)).toEqual(before)
      expect(JSON.parse((await redis.get(cacheKey))!)).toEqual(before)
      expect((await call('admin', 'get', `/${old.id}`).expect(200)).body.data).toEqual(old)
      expect((await call('admin', 'get', `/${next.id}`).expect(200)).body.data).toEqual(next)
    }
    const list = await call('admin', 'get').query({ dictCode: code }).expect(200)
    expect(list.body.data.total).toBe(2)
    expect(list.body.data.items.filter((e: { isDefault: boolean }) => e.isDefault)).toEqual([old])

    await call('admin', 'put', `/${old.id}`, { isDefault: false }).expect(200)
    const unset = await read(code)
    expect(defaults(unset)).toEqual([])
    expect(unset.version).toBeGreaterThan(before.version)
    await call('admin', 'put', `/${next.id}`, { isDefault: true }).expect(200)
    const switched = await read(code)
    expect(defaults(switched)).toEqual([next.value])
    expect(switched.version).toBeGreaterThan(unset.version)
    expect(await read(code)).toEqual(switched)
    expect(JSON.parse((await redis.get(cacheKey))!)).toEqual(switched)
    expect((await call('admin', 'get', `/${old.id}`).expect(200)).body.data.isDefault).toBe(false)
  })

  it.each(['single', 'batch'])(
    'a %s soft-delete frees the default slot and refreshes the cache',
    async (mode) => {
      const code = await dict()
      const old = await add(entryBody(code, { isDefault: true }))
      const before = await read(code)
      expect(defaults(before)).toEqual([old.value])
      if (mode === 'single') await call('admin', 'delete', `/${old.id}`).expect(200)
      else await call('admin', 'post', '/batch-delete', { ids: [old.id] }).expect(200)
      await call('admin', 'get', `/${old.id}`).expect(404)
      expect(
        await ds.query('SELECT is_default, deleted_at FROM cfg_dict_entry WHERE id = ?', [old.id]),
      ).toEqual([{ is_default: 1, deleted_at: expect.any(Date) }])
      const removed = await read(code)
      expect(removed.entries).toEqual([])
      expect(removed.version).toBeGreaterThan(before.version)
      const next = await add(entryBody(code, { isDefault: true }))
      const fresh = await read(code)
      expect(fresh.entries.map((e) => e.value)).toEqual([next.value])
      expect(defaults(fresh)).toEqual([next.value])
      expect(fresh.version).toBeGreaterThan(removed.version)
    },
  )

  it('a disabled default still occupies the slot while the cached read hides it', async () => {
    const code = await dict()
    const old = await add(entryBody(code, { isDefault: true }))
    const next = await add(entryBody(code))
    expect(defaults(await read(code))).toEqual([old.value])
    await call('admin', 'put', `/${old.id}/enabled`, { enabled: false }).expect(200)
    const disabled = await read(code)
    expect(disabled.entries.map((e) => e.value)).toEqual([next.value])
    expect(defaults(disabled)).toEqual([])
    duplicate(await create(entryBody(code, { isDefault: true })))
    duplicate(await call('admin', 'put', `/${next.id}`, { isDefault: true }))
    expect((await call('admin', 'get', `/${old.id}`).expect(200)).body.data).toMatchObject({
      isDefault: true,
      enabled: false,
    })
    expect((await call('admin', 'get', `/${next.id}`).expect(200)).body.data.isDefault).toBe(false)
    expect(await read(code)).toEqual(disabled)
    await call('admin', 'put', `/${old.id}/enabled`, { enabled: true }).expect(200)
    expect(defaults(await read(code))).toEqual([old.value])
  })

  it('different dicts may each have a default, even with the same value', async () => {
    const codes = [await dict(), await dict()]
    const value = unique()
    for (const code of codes) {
      await add(entryBody(code, { value, isDefault: true }))
      expect(defaults(await read(code))).toEqual([value])
    }
  })

  it.each(['create', 'update'])(
    'concurrent default %s writes: one wins, one gets 409, one is cached',
    async (mode) => {
      const code = await dict()
      const bodies = [entryBody(code, { isDefault: true }), entryBody(code, { isDefault: true })]
      const rows =
        mode === 'update'
          ? await Promise.all(bodies.map((b) => add({ ...b, isDefault: false })))
          : []
      const before = await read(code)
      expect(defaults(before)).toEqual([])
      // Different values/bodies keep @Idempotent from turning the create loser into a 429.
      const results = await Promise.all(
        bodies.map((b, i) =>
          mode === 'create'
            ? create(b)
            : call('admin', 'put', `/${rows[i].id}`, { isDefault: true }),
        ),
      )
      const success = mode === 'create' ? 201 : 200
      expect(results.map((r) => r.status).sort((a, b) => a - b)).toEqual([success, 409])
      duplicate(results.find((r) => r.status === 409)!)
      const winner = bodies[results.findIndex((r) => r.status === success)]!.value
      const list = await call('admin', 'get').query({ dictCode: code }).expect(200)
      expect(list.body.data.total).toBe(mode === 'create' ? 1 : 2)
      expect(list.body.data.items.filter((e: { isDefault: boolean }) => e.isDefault)).toEqual([
        expect.objectContaining({ value: winner }),
      ])
      const fresh = await read(code)
      expect(defaults(fresh)).toEqual([winner])
      expect(fresh.version).toBeGreaterThan(before.version)
      expect(await read(code)).toEqual(fresh)
    },
  )
})

describe('dict entries (hand-written)', () => {
  it('an entry needs its dict (unknown → 404); a value is unique within its dict only', async () => {
    const value = unique()
    const res = await create(body(value, { dictCode: 'e2e_dict_entry.missing' }))
    expect(res.status).toBe(404)
    expect(res.body.code).toBe(Err.NOT_FOUND.code)
    await add(body(value))
    await add(body(value, { dictCode: OTHER }))
    const dup = await create(body(value, { label: `${value} again` })) // not the same body: 429
    expect(dup.status).toBe(409)
    expect(dup.body.code).toBe(Err.DUPLICATE.code)
  })

  it('the list of one dict: dictCode equals, by sort order', async () => {
    const tag = unique()
    const b = await add(body(`${tag}-b`, { dictCode: OTHER, sortNo: 2 }))
    const a = await add(body(`${tag}-a`, { dictCode: OTHER, sortNo: 1 }))
    const res = await call('admin', 'get').query({ dictCode: OTHER, sort: 'sortNo,id' }).expect(200)
    const mine = idsOf(res).filter((id: number) => [a.id, b.id].includes(id))
    expect(mine).toEqual([a.id, b.id])
    expect(res.body.data.items.every((e: { dictCode: string }) => e.dictCode === OTHER)).toBe(true)
  })

  it('per-locale labels without blanks; the tag type is one of settings.tag_type or none', async () => {
    const row = await add(body(unique(), { labelI18n: { 'en-US': 'English', 'zh-CN': ' ' } }))
    expect(row.labelI18n).toEqual({ 'en-US': 'English' })
    for (const tagType of ['primary', 'success', 'info', 'warning', 'danger'])
      await call('admin', 'put', `/${row.id}`, { tagType }).expect(200)
    await call('admin', 'put', `/${row.id}`, { tagType: 'rainbow' }).expect(400)
    // the form's cleared select
    await call('admin', 'put', `/${row.id}`, { tagType: '' }).expect(200)
    expect((await call('admin', 'get', `/${row.id}`)).body.data.tagType).toBeNull()
    const codes = (await ds.query(
      "SELECT value FROM cfg_dict_entry WHERE dict_code = 'settings.tag_type' ORDER BY sort_no",
    )) as { value: string }[]
    expect(codes.map((c) => c.value)).toEqual(['primary', 'success', 'info', 'warning', 'danger'])
  })
})
